SELECT id, user_id, parent_id, name, sort_order, status, created_time, update_time, deleted
FROM category
WHERE user_id = #{userId}
  AND update_time > #{since}
ORDER BY update_time ASC
LIMIT #{limit}

SELECT id, user_id, parent_id, name, sort_order, status, created_time, update_time, deleted
FROM category
WHERE id = #{id}
